  rays = rays || 18;
  var pts = [];
  for (var i = 0; i < rays * 2; i++) {
    var ang = -Math.PI / 2 + i * Math.PI / rays;
    var rr = (i % 2 === 0) ? r : r * 0.36;
    pts.push([x + Math.cos(ang) * rr, y + Math.sin(ang) * rr]);
  }
  var poly = g.polygon(pts.map(function (p) { return p[0] + ',' + p[1]; }).join(' '))
    .fill(colors.gold)
    .stroke({ color: colors.gold2, width: 1.4 })
