function clamp(x, a, b) {
  return Math.max(a, Math.min(b, x));
}

function addHover(el, tip, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  el.on('click', function () { showPopup(title, body); });
  return el;
}

function txt(g, s, x, y, size, anchor, weight) {
  return g.text(s)
    .move(x, y)
    .font({
      family: 'Arial, Helvetica, sans-serif',
      size: size,
      anchor: anchor || 'middle',
      weight: weight || 'normal'
    })
    .fill(colors.text);
}

function world(c, r, p) {
  return { x: c.x + p[0] * r, y: c.y + p[1] * r };
}

function arrow(g, c, r, a, width, opacity) {
  var p1 = world(c, r, [a[0], a[1]]);
  var p2 = world(c, r, [a[2], a[3]]);
  var line = g.line(p1.x, p1.y, p2.x, p2.y)
    .stroke({ color: colors.arrow, width: width || 3.8, linecap: 'butt' })
    .opacity(opacity == null ? 1 : opacity);
  line.marker('end', arrowMarker);
  return line;
}

function starburst(g, x, y, r, rays, gen, opacity) {
  var pts = [];
  for (var i = 0; i < rays * 2; i++) {
    var ang = -Math.PI / 2 + i * Math.PI / rays;
    var rr = (i % 2 === 0) ? r : r * 0.30;
    pts.push([x + Math.cos(ang) * rr, y + Math.sin(ang) * rr]);
  }
  var poly = g.polygon(pts.map(function (p) { return p[0] + ',' + p[1]; }).join(' '))
    .fill(colors.gold)
    .stroke({ color: colors.gold2, width: 1.1 })
    .opacity(opacity == null ? 0.98 : opacity);
  poly.data('gen', gen || 0);
  addHover(
    poly,
    'Fission event: a struck nucleus releases energy and more neutrons.',
    'Fission event',
    'Each gold burst represents the same microscopic fission process. Criticality changes how many emitted neutrons stay in the sample, not what one fission does.'
  );
  var core = g.circle(r * 0.32).center(x, y).fill('#fff7ad').opacity(opacity == null ? 0.96 : opacity);
  core.data('gen', gen || 0);
  addHover(
    core,
    'Fission event: a struck nucleus releases energy and more neutrons.',
    'Fission event',
    'Each burst marks a nucleus that fissions after absorbing a neutron.'
  );
  return poly;
}

function radiusForSub(m) {
  return 98 + 70 * clamp(m, 0.4, 1.2);
}

function radiusForCritical(m) {
  return 162 + 48 * clamp(m, 0.4, 1.2);
}

function leakageFromRadius(r) {
  return clamp(0.90 - 0.62 * ((r - 126) / (220 - 126)), 0.18, 0.82);
}

function leakageWords(v) {
  if (v > 0.62) return 'high';
  if (v > 0.38) return 'moderate';
  return 'low';
}

function captureWords(v) {
  if (v > 0.62) return 'high';
  if (v > 0.38) return 'moderate';
  return 'low';
}

function incoming(g, c, r) {
  var start = { x: c.x - r * 0.90, y: c.y - r * 0.86 };
  var end = { x: c.x - r * 0.42, y: c.y - r * 0.42 };
  var dot = g.circle(22).center(start.x - 16, start.y - 16).fill(neutronGrad).opacity(0.95);
  addHover(
    dot,
    'Incoming initiating neutron',
    'Initiating neutron',
    'The pale dot is a neutron entering the material. It can start a chain reaction only if enough later neutrons are retained instead of leaking out.'
  );
  var line = g.line(start.x, start.y, end.x, end.y).stroke({ color: '#000', width: 4, linecap: 'butt' });
  line.marker('end', arrowMarker);
  addHover(
    line,
    'Incoming neutron path',
    'Incoming neutron',
    'One incoming neutron begins the first fission. The later outcome depends on leakage from the whole sample.'
  );
}

function renderPanel(g, kind, c, r, title, panelLabel) {
  g.clear();

  txt(g, title, c.x, 16, 26, 'middle', 'bold');

  var circle = g.circle(2 * r).center(c.x, c.y).fill(colors.fissile).opacity(0.88);
  addHover(
    circle,
    kind === 'sub'
      ? 'Smaller mass: a neutron has a short path to the surface, so leakage is high.'
      : 'Larger mass: neutrons travel through more fissile material before reaching the surface.',
    title,
    kind === 'sub'
      ? 'In the sub-critical sample, many neutrons escape through the boundary before causing another fission, so the chain reaction dies out.'
      : 'In the critical sample, enough emitted neutrons remain inside and trigger later fissions that each generation can replace the previous one.'
  );

  incoming(g, c, r);

  var arrows = kind === 'sub' ? subArrows : critArrows;
  var stars = kind === 'sub' ? subStars : critStars;

  for (var i = 0; i < arrows.length; i++) {
    var ar = arrow(g, c, r, arrows[i], kind === 'sub' ? 3.8 : 3.6, 1);
    var exits = Math.sqrt(arrows[i][2] * arrows[i][2] + arrows[i][3] * arrows[i][3]) > 1;
    addHover(
      ar,
      exits ? 'Escaping neutron: lost from the chain reaction.' : 'Captured neutron path: can trigger another fission.',
      exits ? 'Escaping neutron' : 'Productive capture',
      exits
        ? 'A neutron that crosses the boundary is no longer available to create the next generation of fissions.'
        : 'A neutron path ending at another burst represents productive capture that continues the chain reaction.'
    );
  }

  for (var j = 0; j < stars.length; j++) {
    var p = world(c, r, stars[j]);
    starburst(g, p.x, p.y, kind === 'sub' ? 26 : 25, 18, stars[j][2], 0.98);
  }

  txt(g, panelLabel, c.x, 505, 24, 'middle', 'normal');
}

function updateUiIndicators() {
  var activeCritical = state.massCase === 'Critical mass';
  var r = activeCritical ? radiusForCritical(state.fissileMass) : radiusForSub(state.fissileMass);
  var leak = leakageFromRadius(r);
  var cap = 1 - leak;
  var leakEl = document.getElementById('leakageVal');
  var capEl = document.getElementById('captureVal');
  if (leakEl) leakEl.value = leakageWords(leak) + ' (' + Math.round(leak * 100) + '%)';
  if (capEl) capEl.value = captureWords(cap) + ' (' + Math.round(cap * 100) + '%)';
}

function renderAll() {
  stopAnimation();

  var leftR = state.massCase === 'Sub-critical mass' ? radiusForSub(state.fissileMass) : baseLeftR;
  var rightR = state.massCase === 'Critical mass' ? radiusForCritical(state.fissileMass) : baseRightR;

  renderPanel(leftG, 'sub', leftCenter, leftR, 'Sub-critical mass', '(a)');
  renderPanel(rightG, 'critical', rightCenter, rightR, 'Critical mass', '(b)');
  animG.clear();
  updateUiIndicators();
}

function update_fissileMass(v) {
  state.fissileMass = v;
  var out = document.getElementById('fissileMassVal');
  if (out) out.value = String(v);
  renderAll();
}

function toggle_massCase(on) {
  state.massCase = on ? 'Critical mass' : 'Sub-critical mass';
  renderAll();
}

function stopAnimation() {
  for (var i = 0; i < state.animTimers.length; i++) clearTimeout(state.animTimers[i]);
  state.animTimers = [];
  if (animG) animG.clear();
}

function genLabel(g, text, x, y) {
  g.rect(116, 24).center(x, y + 8).rx(5).fill('#ffffff').opacity(0.88);
  g.text(text).center(x, y + 8)
    .font({ family: 'Arial, Helvetica, sans-serif', size: 15, anchor: 'middle', weight: 'bold' })
    .fill('#000000');
}

function trigger_criticalCascade() {
  var check = document.getElementById('massCaseInput');
  if (check) check.checked = true;
  state.massCase = 'Critical mass';
  if (state.fissileMass < 1) state.fissileMass = 1;

  var slider = document.getElementById('fissileMassInput');
  var out = document.getElementById('fissileMassVal');
  if (slider) slider.value = String(state.fissileMass);
  if (out) out.value = String(state.fissileMass);

  renderAll();

  var r = radiusForCritical(state.fissileMass);
  var c = rightCenter;
  animG.clear();

  var veil = animG.circle(2 * r).center(c.x, c.y).fill('#ffffff').opacity(0.56);
  addHover(
    veil,
    'Animation overlay: fission generations are revealed in sequence.',
    'Critical cascade',
    'The animation reveals generations. The individual fission event is unchanged; the larger mass retains enough neutrons for later generations to appear.'
  );

  var incomingDot = animG.circle(22).center(c.x - r * 0.90 - 16, c.y - r * 0.86 - 16).fill(neutronGrad).opacity(0);
  var incomingLine = animG.line(c.x - r * 0.90, c.y - r * 0.86, c.x - r * 0.42, c.y - r * 0.42)
    .stroke({ color: '#000', width: 4, linecap: 'butt' }).opacity(0);
  incomingLine.marker('end', arrowMarker);

  var genGroups = [animG.group(), animG.group(), animG.group(), animG.group()];
  for (var i = 0; i < critStars.length; i++) {
    var gen = clamp(critStars[i][2], 1, 4);
    var p = world(c, r, critStars[i]);
    starburst(genGroups[gen - 1], p.x, p.y, 25, 18, gen, 0);
  }

  var labels = [
    { text: '1 neutron', x: c.x - r * 0.78, y: c.y - r * 0.88 },
    { text: '2 fissions', x: c.x - r * 0.34, y: c.y - r * 0.56 },
    { text: '4 fissions', x: c.x - r * 0.06, y: c.y + r * 0.00 },
    { text: '8 fissions', x: c.x + r * 0.42, y: c.y + r * 0.58 }
  ];

  var labelGroups = [];
  for (var k = 0; k < labels.length; k++) {
    var lg = animG.group().opacity(0);
    genLabel(lg, labels[k].text, labels[k].x, labels[k].y);
    labelGroups.push(lg);
  }

  function later(ms, fn) {
    state.animTimers.push(setTimeout(fn, ms));
  }

  incomingDot.animate(300).opacity(1);
  incomingLine.animate(300).opacity(1);
  labelGroups[0].animate(300).opacity(1);

  later(600, function () {
    labelGroups[1].animate(300).opacity(1);
    genGroups[0].animate(320).opacity(1);
  });
  later(1250, function () {
    labelGroups[2].animate(300).opacity(1);
    genGroups[1].animate(320).opacity(1);
  });
  later(1900, function () {
    labelGroups[3].animate(300).opacity(1);
    genGroups[2].animate(320).opacity(1);
  });
  later(2550, function () {
    genGroups[3].animate(360).opacity(1);
  });
}

var demoSteps = [
  {
    title: 'Start below critical mass',
    narration: 'In the smaller sample, many neutron arrows leave the blue circle before striking another nucleus. The escape fraction is high, so the chain reaction fades out after only a few fissions.',
    state: { massCase: 'Sub-critical mass', fissileMass: 0.6 }
  },
  {
    title: 'Increase the mass',
    narration: 'Drag the mass slider upward and watch the blue circle grow. With more material between each fission site and the surface, fewer neutrons escape and more are captured productively.',
    state: { massCase: 'Sub-critical mass', fissileMass: 0.9 }
  },
  {
    title: 'Reach critical mass',
    narration: 'At the critical case, the larger circle contains enough fissile material that neutron production balances losses by escape and nonproductive absorption. The diagram now shows most arrows staying inside and reaching other fission sites.',
    state: { massCase: 'Critical mass', fissileMass: 1 }
  },
  {
    title: 'Watch the cascade',
    narration: 'Run the chain-reaction animation in the critical sample: one incoming neutron initiates fission, then later generations spread as 2, 4, and 8 fission events across the larger mass.',
    state: { massCase: 'Critical mass', fissileMass: 1 }
  }
];

function applyStep(i) {
  state.step = clamp(i, 0, demoSteps.length - 1);
  var step = demoSteps[state.step];

  var narration = document.getElementById('demoNarration');
  var label = document.getElementById('stepLabel');
  if (narration) narration.textContent = step.narration;
  if (label) label.textContent = (state.step + 1) + ' / ' + demoSteps.length + ': ' + step.title;

  var check = document.getElementById('massCaseInput');
  var slider = document.getElementById('fissileMassInput');
  var out = document.getElementById('fissileMassVal');

  if (check) check.checked = step.state.massCase === 'Critical mass';
  if (slider) slider.value = String(step.state.fissileMass);
  if (out) out.value = String(step.state.fissileMass);

  state.massCase = step.state.massCase;
  state.fissileMass = step.state.fissileMass;
  renderAll();

  if (state.step === 3) {
    state.animTimers.push(setTimeout(function () { trigger_criticalCascade(); }, 250));
  }
}

function nextStep() {
  applyStep(Math.min(demoSteps.length - 1, state.step + 1));
}

function prevStep() {
  applyStep(Math.max(0, state.step - 1));
}

